    $problems=New-Object 'System.Collections.Generic.List[object]';$rows=New-Object 'System.Collections.Generic.List[object]';$backupBytes=[long]0
    foreach($i in $package.Plan.Items){Assert-WsmCancellationBoundary $CancellationToken 'RestorePreviewItem';if($i.Decision -ne 'Include'){continue};$spec=$i.MigrationSpec;$action='Create';$owned=@($state.Items | Where-Object ItemId -CEQ $i.ItemId);$reason='';$existing=$null
