            elseif($spec.PSObject.Properties['SettingTransition']){Assert-WsmSettingTransition $spec.SettingTransition | Out-Null;$intent=Get-WsmSettingTransitionIntent $spec.SettingTransition $package.Manifest.Target.Fingerprint;$action='ApplySettingTransition';if($spec.SettingTransition.RequiredPhase -eq 'CutoverReady'){$reason='Reviewed setting is applied and read back during isolated staging; its external dependency gate remains due before activation.'}}
            elseif($spec.Adapter -eq 'ManualWorkflow'){$action='ManualProcedure';$reason=$spec.Procedure}
            else{foreach($command in (Get-WsmAdapterRequiredCommands $spec.Adapter)){if(-not (Get-Command $command -ErrorAction SilentlyContinue)){throw ('Missing target dependency: '+$command)}};$receipts=@();if($spec.Adapter -ceq 'ScheduledTask'){$allReceipts=Get-WsmTaskSecurityOwnershipReceipts $state;$receipts=Get-WsmTaskSecurityReceiptsForSpec $spec $allReceipts;Assert-WsmResolvableSddl ([string]$spec.Desired.SecuritySddl);foreach($folderSpec in @($spec.Desired.FolderSecurity)){Assert-WsmResolvableSddl ([string]$folderSpec.SecuritySddl)};[void](Test-WsmTaskSecurityFolderPreparation -Folders @($spec.Desired.FolderSecurity) -SharedReceipts $receipts)}elseif($spec.Adapter -ceq 'Service' -and $spec.Desired.PSObject.Properties['SecuritySddl']){Assert-WsmResolvableSddl ([string]$spec.Desired.SecuritySddl)};$existing=Get-WsmAdapterState $spec;if($spec.Adapter -ceq 'Service'){[void](Get-WsmServiceAccountCredential $spec.Desired $spec $Secrets)};if($existing.Exists){if($spec.Adapter -eq 'WindowsFeature'){$action='VerifyExisting'}else{if(-not $owned.Count -or $owned[0].CreatedByTool -ne $true){throw 'Existing object conflict; automatic overwrite prohibited.'};$check=Test-WsmAdapterConfiguration $spec Staged $receipts;if(-not $check.Passed){throw ('Owned target configuration drift: '+($check.Problems -join '; '))};$action='VerifyAndSkip'}}elseif($spec.PSObject.Properties['SecretRef'] -and $spec.SecretRef){[void](Get-WsmSecret $spec $Secrets)}}
