    if($root[0].Directory){[void][IO.Directory]::CreateDirectory($staging)}
    $maxDepth=0
    Read-WsmArtifactLines $index $Package.Manifest.ArtifactsHash $CancellationToken | ForEach-Object { $row=$_;Assert-WsmCancellationBoundary $CancellationToken 'FileArtifact';if($row.ItemId -ceq $Item.ItemId){$dest=$staging;if($row.RelativePath){$dest=Join-Path $staging $row.RelativePath};if($dest.Length -gt 239){throw 'Target staging path exceeds verified long-path limit.'};if($row.Directory){[void][IO.Directory]::CreateDirectory($dest);$depth=0;if($row.RelativePath){$depth=$row.RelativePath.Split([char]92).Length};$maxDepth=[Math]::Max($maxDepth,$depth)}else{Restore-WsmPayloadBytes $row $Package.Root $dest $CancellationToken;Set-WsmFileMetadata $dest $row.Metadata $SidMap}} }
