function Test-WsmFileScope($Item,$Package,[string]$Target,[hashtable]$SidMap=@{},$CancellationToken=$null) {
    $SidMap=Resolve-WsmIdentityMap $Package.Plan $SidMap;$aclPolicy='Exact';if($Item.MigrationSpec.PSObject.Properties['AclControlPolicy']){$aclPolicy=$Item.MigrationSpec.AclControlPolicy}
    $problems=New-Object 'System.Collections.Generic.List[string]';$expectedCount=[long]0;$problemCount=[long]0
    Read-WsmArtifactLines (Join-Path $Package.Root 'artifacts.jsonl') $Package.Manifest.ArtifactsHash $CancellationToken | ForEach-Object {
        $row=$_;Assert-WsmCancellationBoundary $CancellationToken 'FileScopeVerifyArtifact';if($row.ItemId -ceq $Item.ItemId){$expectedCount++;$path=$Target;if($row.RelativePath){$path=Join-Path $Target $row.RelativePath};$reason=''
            if($row.Directory -ne [IO.Directory]::Exists($path) -or (-not $row.Directory -and -not [IO.File]::Exists($path))){$reason='Absent/type mismatch'}
            else{try{Assert-WsmNoReparse $path;if(-not $row.Directory -and ((New-Object IO.FileInfo($path)).Length -ne $row.Data.Bytes -or (Get-WsmCancellableFileHash $path $CancellationToken 'FileScopeVerifyHashBuffer') -ine $row.Data.Hash)){$reason='Content mismatch'};$meta=Get-WsmFileMetadata $path $row.Metadata.MetadataMode;if(-not (Test-WsmSddlMatch (Convert-WsmMappedSddl $row.Metadata.Sddl $SidMap) $meta.Sddl $aclPolicy)){$reason='ACL mismatch expected '+(Convert-WsmMappedSddl $row.Metadata.Sddl $SidMap)+' / actual '+$meta.Sddl};if($meta.Attributes -ne $row.Metadata.Attributes){$reason='Attributes mismatch expected '+$row.Metadata.Attributes+' / actual '+$meta.Attributes}}catch [OperationCanceledException] {throw}catch{$reason='Unreadable/special artifact'}}
            if(-not $reason -and ([DateTimeOffset]::Parse($meta.CreationUtc).UtcDateTime.Ticks -ne [DateTimeOffset]::Parse($row.Metadata.CreationUtc).UtcDateTime.Ticks -or [DateTimeOffset]::Parse($meta.LastWriteUtc).UtcDateTime.Ticks -ne [DateTimeOffset]::Parse($row.Metadata.LastWriteUtc).UtcDateTime.Ticks)){$reason='File timestamp mismatch'}
            if($reason){$problemCount++;if($problems.Count -lt 100){$problems.Add($reason+': '+$row.RelativePath)}}
        }
    }
    if([IO.Directory]::Exists($Target) -or [IO.File]::Exists($Target)){$actualCount=[long]0;Get-WsmScopeEntries ([pscustomobject]@{SourcePath=$Target;ExcludedRelativePaths=@()}) $Package.Root $CancellationToken | ForEach-Object {$actualCount++};if($actualCount -ne $expectedCount){$problemCount++;$problems.Add('Unexpected target entry count.')}}
    $digest='';if(-not $problemCount){$digest=Get-WsmFileScopeDigest $Target $Item.MigrationSpec.Metadata $CancellationToken};[pscustomobject]@{Passed=($problemCount -eq 0);Problems=$problems.ToArray();ProblemCount=$problemCount;ProblemsTruncated=($problemCount -gt $problems.Count);ActualHash=$digest}
}
function Invoke-WsmRestore {
