            if($spec.Adapter -eq 'ManualWorkflow'){try{Assert-WsmCancellationBoundary $CancellationToken 'BeforeItem'}catch [OperationCanceledException] {$cancel=$_.Exception;$failure=Get-WsmFailureDetails $_;$state.Stage='Cancelled';$detail=[pscustomobject]@{Status='Cancelled';Boundary=[string]$cancel.Data['CancellationBoundary'];OperationId=[string]$cancel.Data['OperationId'];ManifestHash=$ExpectedHash;Generation=$package.Manifest.Generation;NativeDiagnostics=$failure.NativeDiagnostics};Add-WsmJournal $paths $state 'OperationCancelled' $item.ItemId $detail;throw};$result=[pscustomobject]@{ItemId=$item.ItemId;Status='ManualEvidenceRequired';CreatedByTool=$false;ActualHash='';Backup='';Target='';Error='Dedicated product procedure and business evidence required';NativeCode=$null}}
