                elseif($spec.PSObject.Properties['SettingTransition']){$transitionReceipt=Invoke-WsmSettingTransitionForPhase $item $package $paths $state StagedDependencyVerified;$actual=Get-WsmHashText ($transitionReceipt | ConvertTo-Json -Depth 20 -Compress);$check=Test-WsmAdapterConfiguration $spec Staged;if(-not $check.Passed){throw ($check.Problems -join '; ')}}
                elseif($spec.Adapter -eq 'FileScope'){$r=Invoke-WsmFileScopeRestore $item $package $paths $state $SidMap $CancellationToken;$actual=$r.ActualHash;$backup=$r.Backup;$target=$r.Target}
                else{$before=Get-WsmAdapterState $spec;if($before.Exists){throw 'Target object appeared after preview; do not overwrite.'};if($spec.Adapter -eq 'WindowsFeature'){$bootBefore=Get-WsmBootStamp;$installerBaseline=Get-WsmInstallerSnapshot;$installerBaselinePath=Join-Path $paths.Root ($item.ItemId+'.installer-baseline.json');Write-WsmJson $installerBaselinePath $installerBaseline;$installerBaselineHash=(Get-FileHash -LiteralPath $installerBaselinePath).Hash};$pending=[pscustomobject]@{InstallerBaselinePath=$installerBaselinePath;InstallerBaselineHash=$installerBaselineHash;BootBefore=$bootBefore;ItemId=$item.ItemId;Phase='AdapterCreating';Adapter=$spec.Adapter;ManifestHash=$ExpectedHash;AbsentBefore=$true;BeforeHash=(Get-WsmHashText ($before | ConvertTo-Json -Compress -Depth 15));FolderCreateIntents=@();AuxiliaryOwnership=@()};$state.PendingOperations=@($state.PendingOperations | Where-Object ItemId -CNE $item.ItemId)+@($pending);Add-WsmJournal $paths $state 'AdapterIntent' $item.ItemId $pending;Write-WsmJson (Join-Path $paths.Root ($item.ItemId+'.before.json')) $before;if($spec.Adapter -eq 'WindowsFeature'){$bootBefore=Get-WsmBootStamp};$beforeFolderCreate={param($intent)$current=@($state.PendingOperations | Where-Object ItemId -CEQ $item.ItemId)[0];$current.FolderCreateIntents+=@($intent);$detail=[pscustomobject]@{ItemId=$item.ItemId;Adapter='ScheduledTask';ManifestHash=$ExpectedHash;Phase='TaskFolderCreateIntent';Intent=$intent};Add-WsmJournal $paths $state 'TaskFolderCreateIntent' $item.ItemId $detail};$afterFolderCreate={param($receipt)$current=@($state.PendingOperations | Where-Object ItemId -CEQ $item.ItemId)[0];$current.FolderCreateIntents=@($current.FolderCreateIntents | Where-Object OperationId -CNE $receipt.OperationId);$current.AuxiliaryOwnership+=@($receipt);$detail=[pscustomobject]@{ItemId=$item.ItemId;Adapter='ScheduledTask';ManifestHash=$ExpectedHash;Phase='TaskFolderReceipt';Receipt=$receipt};Add-WsmJournal $paths $state 'TaskFolderOwned' $item.ItemId $detail};$allReceipts=@();$priorReceipts=@();$sharedReceipts=@();if($spec.Adapter -ceq 'ScheduledTask'){$allReceipts=Get-WsmTaskSecurityReceiptsForSpec $spec (Get-WsmTaskSecurityOwnershipReceipts $state);$priorReceipts=@($pending.AuxiliaryOwnership);$sharedReceipts=@($allReceipts | Where-Object {$_.OperationId -notin @($priorReceipts | ForEach-Object {$_.OperationId})})};$r=Invoke-WsmAdapterRestore $spec $Secrets $package $installerBaseline $beforeFolderCreate $afterFolderCreate $priorReceipts $sharedReceipts;$reboot=$r.RebootRequired;if($r.PSObject.Properties['AuxiliaryOwnership']){$auxiliaryOwnership=@($r.AuxiliaryOwnership)};if($spec.Adapter -eq 'WindowsFeature'){$installerSafety=$r.InstallerSafety;$installerResult=[pscustomobject]@{NativeTool='Install-WindowsFeature';NativeResult=$r.NativeResult;RestartNeeded=$r.RestartNeeded}};$allReceipts=@();if($spec.Adapter -ceq 'ScheduledTask'){$allReceipts=Get-WsmTaskSecurityReceiptsForSpec $spec (Get-WsmTaskSecurityOwnershipReceipts $state)};$check=Test-WsmAdapterConfiguration $spec Staged $allReceipts;if(-not $check.Passed){throw ($check.Problems -join '; ')};$actual=Get-WsmHashText ($check.Actual | ConvertTo-Json -Depth 15 -Compress)}
                $status='Succeeded';if($reboot){$status='RebootRequired'};$result=[pscustomobject]@{ItemId=$item.ItemId;Status=$status;CreatedByTool=(($record.Count -and $record[0].CreatedByTool) -or $action -notin @('VerifyExisting','SettingTransitionAtCutover'));ActualHash=$actual;Backup=$backup;Target=$target;Error='';NativeCode=0;BootBefore=$bootBefore;InstallerBaselinePath=$installerBaselinePath;InstallerBaselineHash=$installerBaselineHash;InstallerSafety=$installerSafety;InstallerResult=$installerResult;AuxiliaryOwnership=@($auxiliaryOwnership)};if($spec.PSObject.Properties['SettingTransition']){$result.CreatedByTool=$false;$result | Add-Member NoteProperty UpdatedByTool $false;$result | Add-Member NoteProperty SettingTransitionDeferred ($spec.SettingTransition.RequiredPhase -eq 'CutoverReady');if($transitionReceipt){$result.CreatedByTool=[bool]$transitionReceipt.CreatedByTool;$result.UpdatedByTool=[bool]$transitionReceipt.UpdatedByTool;$result | Add-Member NoteProperty SettingTransitionIntent $transitionReceipt.Intent;$result | Add-Member NoteProperty SettingTransitionReceipt $transitionReceipt}}
            }catch [OperationCanceledException] {if(-not $_.Exception.Data['CancellationRequested']){throw};$cancel=$_.Exception;$failure=Get-WsmFailureDetails $_;$state.Stage='Cancelled';$detail=[pscustomobject]@{Status='Cancelled';Boundary=[string]$cancel.Data['CancellationBoundary'];OperationId=[string]$cancel.Data['OperationId'];ManifestHash=$ExpectedHash;Generation=$package.Manifest.Generation;NativeDiagnostics=$failure.NativeDiagnostics};Add-WsmJournal $paths $state 'OperationCancelled' $item.ItemId $detail;throw}catch{$failure=Get-WsmFailureDetails $_;$result=[pscustomobject]@{FailureCategory=$failure.Category;RecoveryHint=$failure.Hint;ExitCode=$failure.ExitCode;NativeDiagnostics=$failure.NativeDiagnostics;ItemId=$item.ItemId;Status='Failed';CreatedByTool=(($record.Count -and $record[0].CreatedByTool) -or @($state.PendingOperations | Where-Object ItemId -CEQ $item.ItemId).Count -gt 0);ActualHash='';Backup='';Target='';Error=$_.Exception.GetType().FullName;NativeCode=$failure.NativeCode;NativeTool=$failure.NativeTool;NativeResult=$failure.NativeResult;HResult=$failure.HResult};$state.Items=@($state.Items | Where-Object ItemId -CNE $item.ItemId)+@($result);$state.Stage='Failed';Add-WsmJournal $paths $state 'ItemFailed' $item.ItemId $result;throw}}
            $state.Items=@($state.Items | Where-Object ItemId -CNE $item.ItemId)+@($result);$state.PendingOperations=@($state.PendingOperations | Where-Object ItemId -CNE $item.ItemId);Add-WsmJournal $paths $state 'ItemCompleted' $item.ItemId $result
        }
        $state.ManifestHash=$ExpectedHash;$state.Generation=$package.Manifest.Generation;$state.Stage='Succeeded';if(@($state.Items | Where-Object Status -NE Succeeded).Count){$state.Stage='ManualEvidenceRequired'};if(@($state.Items | Where-Object Status -EQ RebootRequired).Count){$state.Stage='RebootRequired'};Add-WsmJournal $paths $state 'RestoreCompleted' '' ([pscustomobject]@{Status=$state.Stage;Generation=$state.Generation;ManifestHash=$ExpectedHash});$state
    }
}
function Invoke-WsmSettingTransitionForPhase($Item,$Package,$Paths,$State,[ValidateSet('StagedDependencyVerified','CutoverReady')][string]$Phase) {
    $transition=$Item.MigrationSpec.SettingTransition;Assert-WsmSettingTransition $transition | Out-Null
    $prior=@($State.Items | Where-Object ItemId -CEQ $Item.ItemId)
    if($Phase -eq 'CutoverReady' -and (-not $prior.Count -or -not $prior[0].PSObject.Properties['SettingTransitionReceipt'] -or $prior[0].SettingTransitionReceipt.TransitionHash -cne $transition.TransitionHash)){throw 'CutoverReady setting transitions must have a durable exact readback receipt from isolated staging before external proof or activation.'}
    if($prior.Count -and $prior[0].PSObject.Properties['SettingTransitionReceipt'] -and $prior[0].SettingTransitionReceipt.TransitionHash -ceq $transition.TransitionHash){$current=Get-WsmSettingNativeSnapshot $transition;if(-not (Test-WsmSettingStateEqual $current $transition.After $transition.Adapter)){throw 'SettingTransition target drifted after its durable receipt.'};return $prior[0].SettingTransitionReceipt}
    $pending=[pscustomobject]@{ItemId=$Item.ItemId;Phase='SettingTransition';ManifestHash=$Package.SHA256;TransitionHash=$transition.TransitionHash;Transition=$transition;Intent=$null;Receipt=$null;AppliedPhase=$Phase;RequiredPhase=$transition.RequiredPhase}
    $State.PendingOperations=@($State.PendingOperations | Where-Object ItemId -CNE $Item.ItemId)+@($pending)
    $intent=Get-WsmSettingTransitionIntent $transition $Package.Manifest.Target.Fingerprint;$pending.Intent=$intent
    Add-WsmJournal $Paths $State 'SettingTransitionIntent' $Item.ItemId ([pscustomobject]@{ManifestHash=$Package.SHA256;TransitionHash=$transition.TransitionHash;Intent=$intent;AppliedPhase=$Phase;RequiredPhase=$transition.RequiredPhase})
    $receipt=Invoke-WsmSettingTransitionApply -Transition $transition -Intent $intent -TargetFingerprint $Package.Manifest.Target.Fingerprint -JournalHash $State.JournalHash
    $pending.Receipt=$receipt;Add-WsmJournal $Paths $State 'SettingTransitionReceipt' $Item.ItemId ([pscustomobject]@{ManifestHash=$Package.SHA256;TransitionHash=$transition.TransitionHash;Receipt=$receipt;AppliedPhase=$Phase;RequiredPhase=$transition.RequiredPhase})
    $State.PendingOperations=@($State.PendingOperations | Where-Object ItemId -CNE $Item.ItemId)
    $receipt | Add-Member NoteProperty Intent $intent -Force
    $stored=@($State.Items | Where-Object ItemId -CEQ $Item.ItemId);if($stored.Count){$stored[0] | Add-Member NoteProperty SettingTransitionDeferred $false -Force;$stored[0] | Add-Member NoteProperty SettingTransitionIntent $intent -Force;$stored[0] | Add-Member NoteProperty SettingTransitionReceipt $receipt -Force;$stored[0].CreatedByTool=[bool]$receipt.CreatedByTool;$stored[0] | Add-Member NoteProperty UpdatedByTool ([bool]$receipt.UpdatedByTool) -Force}
    $receipt
}
function Test-WsmSettingTransitionRecordOwnership($Record,$Spec,[string]$TargetFingerprint) {
    if(-not $Record -or -not $Spec -or -not $Spec.PSObject.Properties['SettingTransition']){return $false}
    if(-not $Record.PSObject.Properties['SettingTransitionReceipt'] -or -not $Record.PSObject.Properties['SettingTransitionIntent'] -or -not $Record.PSObject.Properties['CreatedByTool'] -or -not $Record.PSObject.Properties['UpdatedByTool']){return $false}
    $transition=$Spec.SettingTransition;$receipt=$Record.SettingTransitionReceipt;$intent=$Record.SettingTransitionIntent
    if(-not $receipt -or -not $intent){return $false}
    try {
        Assert-WsmSettingTransition $transition | Out-Null
        Assert-WsmSettingTransitionIntent $transition $intent $TargetFingerprint
        $created=($transition.Action -eq 'CreateNew');$updated=($transition.Action -eq 'UpdateReviewed');$readOnly=($transition.Action -in @('KeepTarget','VerifyExternal'));$expectedStatus='Applied';if($readOnly){$expectedStatus='Verified'}
        if($receipt.Kind -cne 'SettingTransitionReceipt' -or $receipt.Status -notin @($expectedStatus,'RecoveredApplied') -or ($receipt.Status -eq 'RecoveredApplied' -and $readOnly) -or $receipt.TransitionHash -ine $transition.TransitionHash -or $receipt.IntentId -cne $intent.IntentId -or $receipt.TargetFingerprint -ine $TargetFingerprint -or [bool]$receipt.CreatedByTool -ne $created -or [bool]$receipt.UpdatedByTool -ne $updated -or (Get-WsmSettingTransitionReceiptHash $receipt) -ine [string]$receipt.ReceiptHash){return $false}
        if([bool]$Record.CreatedByTool -ne $created -or [bool]$Record.UpdatedByTool -ne $updated){return $false}
        $true
    } catch { $false }
}
function Get-WsmRestoreOrder([object[]]$Items) {
    $remaining=@{};foreach($i in $Items){$remaining[$i.ItemId]=$i};$done=@{}
    while($remaining.Count){$ready=@($remaining.Values | Where-Object {$blocked=$false;foreach($d in $_.Dependencies){if($d.Type -eq 'Mandatory' -and $remaining.ContainsKey($d.ItemId)){$blocked=$true}};-not $blocked} | Sort-Object @{e={switch($_.MigrationSpec.Adapter){LocalUser{0};LocalGroup{1};WindowsFeature{2};FileScope{3};Certificate{4};IISPool{5};default{6}}}},ItemId)
        if(-not $ready.Count){$groups=@($remaining.Values | ForEach-Object ConsistencyGroup | Select-Object -Unique);if($groups.Count -ne 1 -or -not $groups[0]){throw 'Unresolved dependency cycle.'};$ready=@($remaining.Values | Sort-Object ItemId);foreach($i in $ready){if(-not $i.ConsistencyOwner -or -not $i.ConsistencyEvidence){throw 'Cycle lacks consistency owner/procedure.'}}}
        foreach($i in $ready){$i;$remaining.Remove($i.ItemId)}
    }
}

function Get-WsmBootStamp {$os=Get-CimInstance Win32_OperatingSystem -ErrorAction Stop;([DateTime]$os.LastBootUpTime).ToUniversalTime().ToString('o')}
function Assert-WsmRebootCompleted($Record){if(-not $Record.PSObject.Properties['BootBefore'] -or -not $Record.BootBefore -or (Get-WsmBootStamp) -ceq $Record.BootBefore){throw 'Installer required reboot has not been verified; restart under reviewed maintenance procedure, then retry staging.'}}
